WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_train_chase'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '火车追及', 'kp-trv-train-chase', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "火车追及"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "两车长度之和 = 速度差 × 超车时间。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“快车从后面追上慢车，直到完全超过慢车，花了 45 秒”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "超车的过程：快车头平齐慢车尾（开始），到快车尾脱离慢车头（结束）。快车比慢车多走了一整个快车长度 + 一整个慢车长度。"}]}, {"type": "katexBlock", "attrs": {"content": "L_{快} + L_{慢} = (V_{快} - V_{慢}) \\times T_{超车}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "不要减去长度：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多人觉得既然是追击（速度用减法），那路程是不是也要用快车长减去慢车长？绝对不是！无论是会车还是超车，要彻底【错开身体】，走过的相对距离必然是两车长度相加！"}]}]}]}$$ AS jsonb), NULL, '火车追及的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "火车追及"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_train_chase", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
